class Solution:
    def countPathsWithXorValue(self, grid: List[List[int]], k: int) -> int:
        mod = 10**9 + 7
        m, n = len(grid), len(grid[0])
        if not any(any(row) for row in grid):
            from math import comb
            return comb(m + n - 2, m - 1) if k == 0 else 0
        prev = [[0] * 16 for _ in range(n)]
        for i in range(m):
            cur = [[0] * 16 for _ in range(n)]
            for j in range(n):
                v = grid[i][j]
                cell = cur[j]
                if i == 0 and j == 0:
                    cell[v] = 1
                    continue
                up = prev[j]
                left = cur[j - 1] if j > 0 else None
                for x in range(16):
                    total = up[x]
                    if left is not None:
                        total += left[x]
                    if total:
                        cell[x ^ v] = total % mod
            prev = cur
        return prev[n - 1][k]
